"""Public computation-only source policy, independent of CUDA availability."""

import ast


IMPORTS = {
    "torch": (None, "torch"),
    "triton": (None, "triton"),
    "triton.language": ("tl", "tl"),
    "math": (None, "math"),
    "typing": (None, "typing"),
}
BUILTINS = {
    "abs", "bool", "float", "int", "len", "max", "min", "range", "round",
    "tuple", "list", "enumerate", "zip", "ValueError", "RuntimeError",
    "TypeError", "AssertionError",
}
FORBIDDEN = {
    "exec", "eval", "compile", "__import__", "open", "os", "sys", "subprocess",
    "ctypes", "socket", "importlib", "pickle", "shutil", "getattr", "setattr",
    "delattr", "globals", "locals", "vars", "dir", "type", "object", "help",
    "breakpoint", "input", "print",
}
MODULE_ATTRIBUTES = {
    "torch": {
        "empty", "empty_like", "zeros", "zeros_like", "full", "full_like",
        "Tensor", "float16", "float32", "float64", "bfloat16", "int8", "int16",
        "int32", "int64", "uint8", "bool",
    },
    "triton": {"jit", "cdiv", "next_power_of_2"},
    "tl": {
        "constexpr", "program_id", "num_programs", "arange", "load", "store",
        "sum", "max", "min", "where", "sqrt", "rsqrt", "exp", "exp2", "log",
        "log2", "abs", "full", "zeros", "cast", "reshape", "broadcast_to",
        "trans", "join", "split", "multiple_of", "max_contiguous", "minimum",
        "maximum", "div_rn", "cdiv", "range", "static_range", "int1", "int8",
        "int16", "int32", "int64", "uint8", "uint16", "uint32", "uint64",
        "float16", "float32", "float64", "bfloat16",
    },
    "math": {"ceil", "floor", "sqrt", "log2", "exp", "log", "isfinite", "inf", "pi"},
    "typing": {"Tuple", "List", "Optional", "Union"},
}
MODULE_CALLS = {
    "torch": {"empty", "empty_like", "zeros", "zeros_like", "full", "full_like"},
    "triton": {"cdiv", "next_power_of_2"},
    "tl": MODULE_ATTRIBUTES["tl"] - {
        "constexpr", "int1", "int8", "int16", "int32", "int64", "uint8", "uint16",
        "uint32", "uint64", "float16", "float32", "float64", "bfloat16",
    },
    "math": MODULE_ATTRIBUTES["math"] - {"inf", "pi"},
    "typing": set(),
}
TENSOR_ATTRIBUTES = {"shape", "dtype", "device", "stride", "numel", "is_contiguous", "to", "reshape"}
TENSOR_CALLS = {"stride", "numel", "is_contiguous", "to", "reshape"}
NODES = (
    ast.Module, ast.Import, ast.alias, ast.FunctionDef, ast.arguments, ast.arg,
    ast.Return, ast.Assign, ast.AnnAssign, ast.AugAssign, ast.For, ast.If,
    ast.Expr, ast.Assert, ast.Raise, ast.Pass, ast.Break, ast.Continue,
    ast.Name, ast.Constant, ast.Attribute, ast.Call, ast.keyword, ast.Subscript,
    ast.Slice, ast.Tuple, ast.List, ast.Dict, ast.Set, ast.IfExp, ast.Compare,
    ast.BoolOp, ast.UnaryOp, ast.BinOp, ast.Lambda, ast.ListComp, ast.SetComp,
    ast.DictComp, ast.GeneratorExp, ast.comprehension, ast.operator, ast.unaryop,
    ast.boolop, ast.cmpop, ast.expr_context,
)


class Rejected(ValueError):
    pass


def immutable(value):
    return type(value) in (int, float, bool, str, bytes, type(None)) or (
        isinstance(value, tuple) and all(immutable(item) for item in value)
    )


class Gate(ast.NodeVisitor):
    def __init__(self, functions, kernels):
        self.functions = functions
        self.kernels = kernels
        self.reserved = set(MODULE_ATTRIBUTES) | BUILTINS | functions
        self.depth = 0

    def generic_visit(self, node):
        if not isinstance(node, NODES):
            raise Rejected(f"Unsupported syntax: {type(node).__name__}")
        super().generic_visit(node)

    def identifier(self, name):
        if "__" in name or name in FORBIDDEN:
            raise Rejected(f"Forbidden identifier: {name}")

    def visit_Import(self, node):
        if self.depth:
            raise Rejected("Imports must be at module scope")
        for alias in node.names:
            if alias.name not in IMPORTS or alias.asname != IMPORTS[alias.name][0]:
                raise Rejected(f"Unsupported import: {alias.name}")

    def visit_Name(self, node):
        self.identifier(node.id)
        if isinstance(node.ctx, ast.Store) and node.id in self.reserved:
            raise Rejected(f"Cannot rebind: {node.id}")

    def visit_arg(self, node):
        self.identifier(node.arg)
        if node.arg in self.reserved:
            raise Rejected(f"Cannot shadow: {node.arg}")
        self.generic_visit(node)

    def visit_Constant(self, node):
        if isinstance(node.value, (str, bytes)):
            text = node.value if isinstance(node.value, str) else node.value.decode("utf-8", "replace")
            if len(text) > 4096 or any(part in text for part in ("/logs", "/tests", "/solution", "reward.json", "__")):
                raise Rejected("Forbidden string literal")

    def visit_Attribute(self, node):
        self.identifier(node.attr)
        if not isinstance(node.ctx, ast.Load):
            raise Rejected("Attribute mutation is forbidden")
        if isinstance(node.value, ast.Name) and node.value.id in MODULE_ATTRIBUTES:
            if node.attr not in MODULE_ATTRIBUTES[node.value.id]:
                raise Rejected(f"Unsupported API: {node.value.id}.{node.attr}")
        elif node.attr not in TENSOR_ATTRIBUTES:
            raise Rejected(f"Unsupported attribute: {node.attr}")
        self.generic_visit(node)

    def visit_Call(self, node):
        target = node.func
        if isinstance(target, ast.Name):
            if target.id not in self.functions | BUILTINS:
                raise Rejected(f"Dynamic call is forbidden: {target.id}")
        elif isinstance(target, ast.Attribute):
            if isinstance(target.value, ast.Name) and target.value.id in MODULE_CALLS:
                if target.attr not in MODULE_CALLS[target.value.id]:
                    raise Rejected(f"Unsupported callable: {target.value.id}.{target.attr}")
            elif target.attr not in TENSOR_CALLS:
                raise Rejected(f"Unsupported method: {target.attr}")
        elif isinstance(target, ast.Subscript):
            if not isinstance(target.value, ast.Name) or target.value.id not in self.kernels:
                raise Rejected("Only declared Triton kernels can use launch syntax")
        else:
            raise Rejected("Dynamic callable is forbidden")
        for keyword in node.keywords:
            if keyword.arg is None:
                raise Rejected("Expanded keyword arguments are forbidden")
            self.identifier(keyword.arg)
            if keyword.arg.startswith("_") or keyword.arg in {
                "extern_libs", "launch_metadata", "launch_enter_hook", "launch_exit_hook",
            }:
                raise Rejected("Compiler hooks are forbidden")
        self.generic_visit(node)

    def visit_FunctionDef(self, node):
        self.identifier(node.name)
        if self.depth:
            raise Rejected("Nested functions are forbidden")
        if node.name in set(MODULE_ATTRIBUTES) | BUILTINS:
            raise Rejected("Cannot shadow a trusted API")
        for decorator in node.decorator_list:
            if not (
                isinstance(decorator, ast.Attribute)
                and isinstance(decorator.value, ast.Name)
                and decorator.value.id == "triton"
                and decorator.attr == "jit"
            ):
                raise Rejected("Only @triton.jit is permitted")
        if len(node.decorator_list) > 1:
            raise Rejected("Repeated decorators are forbidden")
        for default in node.args.defaults + [item for item in node.args.kw_defaults if item is not None]:
            try:
                safe = immutable(ast.literal_eval(default))
            except (ValueError, TypeError):
                safe = False
            if not safe:
                raise Rejected("Defaults must be immutable literals")
        for annotation in [node.returns] + [
            argument.annotation for argument in ast.walk(node.args) if isinstance(argument, ast.arg)
        ]:
            if annotation is not None and any(isinstance(item, ast.Call) for item in ast.walk(annotation)):
                raise Rejected("Annotation calls are forbidden")
        self.depth += 1
        self.generic_visit(node)
        self.depth -= 1


def validate_source(source):
    if len(source.encode("utf-8")) > 131072:
        raise Rejected("Submission exceeds 128 KiB")
    tree = ast.parse(source, filename="candidate.py")
    if sum(1 for node in ast.walk(tree)) > 12000:
        raise Rejected("Submission is too complex")
    functions = {}
    kernels = set()
    for statement in tree.body:
        if isinstance(statement, ast.Import):
            continue
        if isinstance(statement, ast.FunctionDef):
            if statement.name in functions:
                raise Rejected("Duplicate function name")
            functions[statement.name] = statement
            if statement.decorator_list:
                kernels.add(statement.name)
            continue
        if isinstance(statement, ast.Expr) and isinstance(statement.value, ast.Constant) and isinstance(statement.value.value, str):
            continue
        if isinstance(statement, (ast.Assign, ast.AnnAssign)):
            targets = statement.targets if isinstance(statement, ast.Assign) else [statement.target]
            try:
                safe = immutable(ast.literal_eval(statement.value))
            except (ValueError, TypeError):
                safe = False
            if not safe or not all(isinstance(target, ast.Name) for target in targets):
                raise Rejected("Module constants must be immutable literal values")
            if isinstance(statement, ast.AnnAssign) and any(isinstance(item, ast.Call) for item in ast.walk(statement.annotation)):
                raise Rejected("Annotation calls are forbidden")
            continue
        raise Rejected("Module scope may not execute computation")
    if "run" not in functions or "run" in kernels or not kernels or len(functions) > 24:
        raise Rejected("Provide run and at least one @triton.jit kernel")
    arguments = functions["run"].args
    if len(arguments.posonlyargs + arguments.args) != 7 or arguments.vararg or arguments.kwarg or arguments.kwonlyargs:
        raise Rejected("run must take seven positional arguments")
    Gate(set(functions), kernels).visit(tree)
    return tree
